INSERT INTO "public"."Course" ("id", "slug", "title", "description", "longDescription", "thumbnail", "category", "level", "pricePkr", "isFree", "instructorId", "zoomLink", "schedule", "status", "isFeatured", "isCompleted", "completedAt", "requirements", "whatYouLearn", "tags", "enrolledCount", "rating", "reviewCount", "createdAt", "updatedAt") VALUES ('course-1', 'complete-react-nextjs-course', 'Complete React & Next.js Mastery', 'Master React and Next.js from scratch to advanced. Build real-world projects.', 'This comprehensive course covers everything you need to become a proficient React and Next.js developer. Starting from the fundamentals of React components, hooks, and state management, you will progress to building full-stack applications with Next.js, API routes, authentication, and deployment.', 'https://images.unsplash.com/photo-1633356122544-f134324a6cee?w=800&q=80', 'Web_Development', 'intermediate', 4999, false, 'inst-1', 'https://zoom.us/j/1234567890', NULL, 'published', true, false, NULL, '{"Basic HTML & CSS knowledge","JavaScript fundamentals","A computer with internet"}', '{"React hooks and state management","Next.js App Router","TypeScript integration","REST APIs & databases","Authentication & authorization","Deployment on Vercel"}', '{"React","Next.js","TypeScript","Web Dev"}', 342, 4.8, 87, '2024-01-15'::timestamptz, '2024-05-20'::timestamptz);
INSERT INTO "public"."Module" ("id", "courseId", "title", "position") VALUES ('mod-1-1', 'course-1', 'React Fundamentals', 1);
