INSERT INTO "public"."Lesson" ("id", "moduleId", "title", "position", "description", "recordingUrl", "materials", "duration", "date") VALUES ('les-1-1-2', 'mod-1-1', 'JSX and Components', 2, 'Understanding JSX syntax and component creation', 'https://www.youtube.com/watch?v=example2', '[]'::jsonb, '50 min', '2024-05-10'::timestamptz);
