INSERT INTO "public"."Announcement" ("id", "title", "content", "type", "courseId", "authorId", "isActive", "createdAt") VALUES ('ann-4', 'New Lesson Added: TypeScript Advanced Types', 'I have added a new lesson covering advanced TypeScript patterns. Check it out in Module 2!', 'course', 'course-1', 'inst-1', true, '2024-05-20'::timestamptz);
