INSERT INTO "public"."Review" ("id", "studentId", "courseId", "rating", "comment", "createdAt") VALUES ('rev-1', 'student-1', 'course-3', 5, 'Incredible course! Went from Python basics to building real ML models. Bilal is an amazing teacher.', '2024-04-05'::timestamptz);
INSERT INTO "public"."Review" ("id", "studentId", "courseId", "rating", "comment", "createdAt") VALUES ('rev-2', 'student-2', 'course-4', 4, 'Great Figma course for beginners. Clear explanations and good projects. Would love more real-world case studies.', '2024-04-20'::timestamptz);
INSERT INTO "public"."Review" ("id", "studentId", "courseId", "rating", "comment", "createdAt") VALUES ('rev-3', 'student-4', 'course-4', 5, 'Best free design course available anywhere. Zainab explains design principles beautifully.', '2024-05-05'::timestamptz);
INSERT INTO "public"."Review" ("id", "studentId", "courseId", "rating", "comment", "createdAt") VALUES ('rev-4', 'student-5', 'course-1', 5, 'This course got me my first developer job. The Next.js section is gold.', '2024-03-25'::timestamptz);
