INSERT INTO "public"."Testimonial" ("id", "studentName", "studentAvatar", "courseTitle", "rating", "comment", "date") VALUES ('t1', 'Ali Raza', 'https://api.dicebear.com/7.x/initials/svg?seed=Ali+Raza&backgroundColor=1C1C1C&textColor=F5C518', 'Complete React & Next.js Mastery', 5, 'This course completely changed my career. The instructor explains everything clearly and the projects are real-world. Got a job 2 months after completing!', '2024-04-05'::timestamptz);
INSERT INTO "public"."Testimonial" ("id", "studentName", "studentAvatar", "courseTitle", "rating", "comment", "date") VALUES ('t2', 'Ayesha Siddiqui', 'https://api.dicebear.com/7.x/initials/svg?seed=Ayesha+Siddiqui&backgroundColor=1C1C1C&textColor=F5C518', 'Flutter Mobile App Development', 5, 'Best Flutter course I have found! The instructor walks you through everything step by step. Published my first app to Play Store!', '2024-04-20'::timestamptz);
INSERT INTO "public"."Testimonial" ("id", "studentName", "studentAvatar", "courseTitle", "rating", "comment", "date") VALUES ('t3', 'Omar Farooq', 'https://api.dicebear.com/7.x/initials/svg?seed=Omar+Farooq&backgroundColor=1C1C1C&textColor=F5C518', 'Python for Data Science & ML', 5, 'Incredible depth and quality. I went from knowing basic Python to building ML models. The hands-on projects make all the difference.', '2024-05-10'::timestamptz);
INSERT INTO "public"."Testimonial" ("id", "studentName", "studentAvatar", "courseTitle", "rating", "comment", "date") VALUES ('t4', 'Maryam Noor', 'https://api.dicebear.com/7.x/initials/svg?seed=Maryam+Noor&backgroundColor=1C1C1C&textColor=F5C518', 'UI/UX Design with Figma', 4, 'Great course for beginners! I had zero design experience and now I can create professional UI mockups. The free access is amazing.', '2024-05-15'::timestamptz);
INSERT INTO "public"."Testimonial" ("id", "studentName", "studentAvatar", "courseTitle", "rating", "comment", "date") VALUES ('t5', 'Hamza Sheikh', 'https://api.dicebear.com/7.x/initials/svg?seed=Hamza+Sheikh&backgroundColor=1C1C1C&textColor=F5C518', 'Docker & Kubernetes for DevOps', 5, 'Extremely practical course. I use everything I learned here at my job every single day. Worth every rupee!', '2024-05-25'::timestamptz);
INSERT INTO "public"."Testimonial" ("id", "studentName", "studentAvatar", "courseTitle", "rating", "comment", "date") VALUES ('t6', 'Sana Javed', 'https://api.dicebear.com/7.x/initials/svg?seed=Sana+Javed&backgroundColor=1C1C1C&textColor=F5C518', 'Node.js & Express Backend', 4, 'Really comprehensive backend course. Loved the API design section. Would love to see more about GraphQL added!', '2024-06-01'::timestamptz);
